function toast(message,error=false){$('#toast').textContent=message;$('#toast').className='toast'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.add('hidden'),6500)}
async function request(path,options={}){
 const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),20000);
 try{
  const r=await fetch(path,{credentials:'same-origin',cache:'no-store',...options,signal:controller.signal,headers:{...(options.body?{'content-type':'application/json'}:{}),...options.headers}});
  let data;try{data=await r.json()}catch{throw new Error('로그인 상태 또는 서버 연결을 확인해 주세요. 저장 전 입력은 백업해 주세요.')}
  if(!r.ok)throw Object.assign(new Error(data.error||'요청을 완료하지 못했습니다.'),{status:r.status});return data;
 }catch(e){if(e.name==='AbortError')throw new Error('응답이 늦어 요청을 중단했습니다. 입력은 보관됩니다. 연결을 확인한 뒤 다시 시도해 주세요.');throw e}finally{clearTimeout(timeout)}
}
