function snapshotKey(){return 'project-lab-unsaved:'+BOOT.user.id+':'+S.current?.id}
function keepLocalDraft(){if(!S.current||!S.body)return true;try{localStorage.setItem(snapshotKey(),JSON.stringify({body:S.body,baseVersion:S.current.version,saved_at:new Date().toISOString()}));S.localDraftFailed=false;return true}catch{S.localDraftFailed=true;return false}}
function setSaveStatus(message,error=false){const node=$('#save-status');if(node){node.textContent=message+(S.localDraftFailed?' · 브라우저 임시 저장이 불가능합니다. JSON 백업을 권장합니다.':'');node.className='save-status'+(error?' error':'')}if($('#conflict-tools'))$('#conflict-tools').classList.toggle('hidden',!S.conflict)}
function markDirty(){S.dirty=true;keepLocalDraft();setSaveStatus(S.conflict?'다른 기기와 저장 충돌이 있습니다. 입력을 백업한 뒤 최신 버전을 불러오세요.':'변경 내용 저장 대기');clearTimeout(S.timer);if(!S.conflict)S.timer=setTimeout(save,1000)}
function itemFrom(r){return{id:r.id,kind:r.body.kind,title:r.body.title,status:r.body.status,projectId:r.body.projectId,date:r.body.date,review_on:r.body.review_on||'',version:r.version,created_at:r.created_at,updated_at:r.updated_at}}
function updateRecord(r){S.records.set(r.id,r);const item=itemFrom(r),index=S.items.findIndex(x=>x.id===r.id);if(index<0)S.items.unshift(item);else S.items[index]=item;drawNav()}
async function getRecord(id,force=false){const meta=S.items.find(x=>x.id===id),cached=S.records.get(id);if(!force&&cached&&(!meta||meta.version===cached.version))return cached;const r=await request('/api/learning/records/'+encodeURIComponent(id));S.records.set(id,r);return r}
function sameBody(a,b){try{return JSON.stringify(checkedRecord(a))===JSON.stringify(checkedRecord(b))}catch{return false}}
async function save(){
 clearTimeout(S.timer);if(S.conflict)return false;
 if(S.saving){const ok=await S.saving;if(ok&&S.dirty)return save();return ok}
 if(!S.current||!S.dirty)return true;
 const id=S.current.id,version=S.current.version,body=structuredClone(S.body);
 try{checkedRecord(body)}catch(e){keepLocalDraft();setSaveStatus(e.message,true);return false}
 setSaveStatus('서버에 저장 중…');
 S.saving=(async()=>{try{
  let result;
  try{result=await request('/api/learning/records/'+id,{method:'PUT',body:JSON.stringify({version,body})})}
  catch(error){
   if(error.status!==409)throw error;
   let latest;try{latest=await request('/api/learning/records/'+id)}catch{throw error}
   if(latest.version===version+1&&sameBody(latest.body,body))result={record:latest};
   else if(S.uncertain?.id===id&&latest.version===S.uncertain.version+1&&sameBody(latest.body,S.uncertain.body)){
    result=await request('/api/learning/records/'+id,{method:'PUT',body:JSON.stringify({version:latest.version,body})});
   }else throw error;
  }
  S.uncertain=null;S.lastSaveError='';updateRecord(result.record);
  if(S.current?.id===id){S.current=result.record;if(JSON.stringify(S.body)===JSON.stringify(body)){S.dirty=false;try{localStorage.removeItem(snapshotKey())}catch{}}setSaveStatus((S.dirty?'새 변경 내용 저장 대기 · ':'서버에 저장됨 · ')+fmt(result.record.updated_at)+' · v'+result.record.version)}return true;
 }catch(e){
  if(!e.status||e.status>=500)S.uncertain={id,version,body};
  S.conflict=e.status===409;keepLocalDraft();setSaveStatus(e.message,true);
  if(S.lastSaveError!==e.message){toast(e.message,true);S.lastSaveError=e.message}return false;
 }finally{S.saving=null}})();return S.saving;
}
async function guard(){if(S.dirty||S.saving)return save();return true}
