async function create(body,id=crypto.randomUUID()){
 let r;try{r=await request('/api/learning/records/'+id,{method:'PUT',body:JSON.stringify({version:0,body})})}
 catch(e){if(e.status!==409)throw e;const existing=await getRecord(id,true);if(!sameBody(existing.body,body))throw Object.assign(new Error('이전 요청이 이미 저장되어 있습니다. 기존 기록을 열어 수정하거나 현재 입력을 백업해 주세요.'),{record:existing});r={record:existing}}
 updateRecord(r.record);return r.record;
}
