function sourcePanel(){const b=S.body,source=b.source;let html=source?'<div class="card source-note"><strong>시작한 자료</strong>'+esc(source.title)+'<p>'+esc(source.what)+'</p>'+(source.url?'<a href="'+esc(source.url)+'" target="_blank" rel="noopener">원문 확인 ↗</a>':'')+'</div>':'';if(b.sourceIds?.length){html+='<div class="card"><h3>연결된 내 근거</h3>'+b.sourceIds.map(id=>{const item=S.items.find(i=>i.id===id),version=b.provenance?.sources?.find(s=>s.id===id)?.version;return '<p><a href="#/record/'+esc(id)+'">'+esc(item?.title||'원본 기록')+'</a><br><span class="small">'+(version===0?'가져오기 전 출처 버전 재확인 필요 · ':version?'초안 시점 v'+version+' · ':'')+(item?'현재 v'+item.version:'현재 목록에 없음')+(item&&version&&item.version!==version?' · 원본 변경됨, 다시 검토하세요.':'')+'</span></p>'}).join('')+'</div>'}return html}
